select ok(check_value,description) from (values
  ((select source_kind='NEED_GENERATION' and wholesale_order_id is null from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600'),'batch uses only the Need Generation source family'),
  ((select row(origin_need_generation_run_id,origin_need_generation_run_version,origin_need_generation_release_snapshot_id)=row('b6400000-0000-0000-0000-000000000500'::uuid,3,'b6400000-0000-0000-0000-000000000540'::uuid) from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600'),'origin release triple is exact'),
  ((select row(current_need_generation_run_id,current_need_generation_run_version,current_need_generation_release_snapshot_id)=row('b6400000-0000-0000-0000-000000000500'::uuid,3,'b6400000-0000-0000-0000-000000000540'::uuid) from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600'),'current release triple is exact'),
  ((select count(*)=1 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600'),'one stable operational line exists'),
  ((select source_kind='NEED_GENERATION' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line source kind is exact'),
  ((select service_date=date '2026-12-07' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line date is exact'),
  ((select customer_id='b6400000-0000-0000-0000-000000000100' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line customer is exact'),
  ((select school_id='b6400000-0000-0000-0000-000000000120' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line School is exact'),
  ((select delivery_location_id='b6400000-0000-0000-0000-000000000101' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line destination is exact'),
  ((select ingredient_id='b6400000-0000-0000-0000-000000000140' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line Ingredient is exact'),
  ((select controlled_unit_id='b6400000-0000-0000-0000-000000000130' from atlas_planning.confirmed_need_lines where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'stable line Unit is exact'),
  ((select count(*)=1 from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_id='b6400000-0000-0000-0000-000000000610'),'one revision exists initially'),
  ((select confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600' from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision owner batch is exact'),
  ((select source_kind='NEED_GENERATION' from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision source kind is exact'),
  ((select need_generation_run_id='b6400000-0000-0000-0000-000000000500' from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision run is exact'),
  ((select need_generation_run_version=3 from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision run version is exact'),
  ((select need_generation_release_snapshot_id='b6400000-0000-0000-0000-000000000540' from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision snapshot is exact'),
  ((select theoretical_quantity=12 from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision theoretical total is exact'),
  ((select confirmed_quantity=12 from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision confirmed quantity is initially exact'),
  ((select is_current from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision is current'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'revision has two members'),
  ((select row(count(distinct theoretical_need_line_id),count(distinct need_generation_release_snapshot_line_id))=row(2::bigint,2::bigint) from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'membership retains both source and release lines'),
  ((select sum(source_theoretical_quantity)=12 from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'source quantity sum is exact'),
  ((select sum(controlled_contribution_quantity)=12 from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'controlled quantity sum is exact'),
  ((select bool_and(source_theoretical_quantity=controlled_contribution_quantity) from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'no quantity conversion occurs'),
  ((select bool_and(source_unit_id=controlled_unit_id) from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'no unit conversion occurs'),
  ((select bool_and(confirmed_need_batch_id='b6400000-0000-0000-0000-000000000600') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact batch owner'),
  ((select bool_and(confirmed_need_line_id='b6400000-0000-0000-0000-000000000610') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact stable-line owner'),
  ((select bool_and(need_generation_run_id='b6400000-0000-0000-0000-000000000500') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact run'),
  ((select bool_and(need_generation_run_version=3) from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact run version'),
  ((select bool_and(need_generation_release_snapshot_id='b6400000-0000-0000-0000-000000000540') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact snapshot'),
  ((select bool_and(service_date=date '2026-12-07') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact date'),
  ((select bool_and(customer_id='b6400000-0000-0000-0000-000000000100') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact customer'),
  ((select bool_and(school_id='b6400000-0000-0000-0000-000000000120') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact School'),
  ((select bool_and(delivery_location_id='b6400000-0000-0000-0000-000000000101') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact destination'),
  ((select bool_and(ingredient_id='b6400000-0000-0000-0000-000000000140') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members repeat the exact Ingredient'),
  ((select bool_and(source_unit_id='b6400000-0000-0000-0000-000000000130' and controlled_unit_id='b6400000-0000-0000-0000-000000000130') from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000620'),'members retain the exact source and controlled Unit'),
  ((select count(*)=2 from atlas_planning.need_generation_release_snapshot_lines snapshot_line join atlas_planning.theoretical_need_lines theoretical using (theoretical_need_line_id) where snapshot_line.need_generation_release_snapshot_id='b6400000-0000-0000-0000-000000000540' and theoretical.line_disposition='ACTIVE' and theoretical.ingredient_id='b6400000-0000-0000-0000-000000000140'),'active release has exactly the grouped two-line source set')
) checks(check_value,description);

