  ((select predecessor_revision_id='b6400000-0000-0000-0000-000000000620' from atlas_planning.confirmed_need_line_revisions where confirmed_need_line_revision_id='b6400000-0000-0000-0000-000000000750'),'new revision points to its predecessor'),
